package domain

import (
	"fmt"
	"sort"
	"strings"
)

// RenderEnv renders .env content with optional comments above each variable.
func RenderEnv(values map[string]string, comments map[string]string) string {
	var buf strings.Builder

	keys := make([]string, 0, len(values))
	for k := range values {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, k := range keys {
		if comments != nil {
			if comment, ok := comments[k]; ok && strings.TrimSpace(comment) != "" {
				for _, line := range strings.Split(comment, "\n") {
					fmt.Fprintf(&buf, "# %s\n", strings.TrimSpace(line))
				}
			}
		}
		fmt.Fprintf(&buf, "%s=%s\n", k, FormatValue(values[k]))
	}

	return buf.String()
}

// RenderMCPEnv renders .cursor/mcp.env content from the supplied tokens.
func RenderMCPEnv(tokens map[string]string) string {
	var buf strings.Builder
	buf.WriteString("# Auto-generated by manova CLI for Cursor MCP servers\n")
	buf.WriteString("# File permissions must remain 0600 for security.\n\n")

	keys := make([]string, 0, len(tokens))
	for k := range tokens {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	for _, k := range keys {
		fmt.Fprintf(&buf, "%s=%s\n", k, FormatValue(tokens[k]))
	}

	return buf.String()
}

// FormatValue formats a string for output in an env file, quoting when necessary.
func FormatValue(val string) string {
	if val == "" {
		return `""`
	}

	needsQuotes := strings.ContainsAny(val, " \t\n\"'#$`\\") || strings.HasPrefix(val, " ") || strings.HasSuffix(val, " ")
	if !needsQuotes {
		return val
	}

	escaped := strings.ReplaceAll(val, `\`, `\\`)
	escaped = strings.ReplaceAll(escaped, `"`, `\"`)
	escaped = strings.ReplaceAll(escaped, "\n", `\n`)
	escaped = strings.ReplaceAll(escaped, "\r", `\r`)
	escaped = strings.ReplaceAll(escaped, "\t", `\t`)
	escaped = strings.ReplaceAll(escaped, `$`, `\$`)

	return `"` + escaped + `"`
}

// ValuesFromSchema maps a schema to its default values and descriptions.
func ValuesFromSchema(schema *EnvSchema, overrides map[string]string) (values, comments map[string]string) {
	values = make(map[string]string)
	comments = make(map[string]string)
	for _, v := range schema.Variables {
		comments[v.Name] = v.Description
		if val, ok := overrides[v.Name]; ok {
			values[v.Name] = val
		} else {
			values[v.Name] = v.Default
		}
	}
	return values, comments
}
